     };

     function escapeHtml(value) {
       return String(value)
         .replace(/&/g, "&amp;")
         .replace(/</g, "&lt;")
         .replace(/>/g, "&gt;")
         .replace(/"/g, "&quot;")
         .replace(/'/g, "&#039;");
     }

     function validateField(id, value) {
       const trimmedValue = value.trim();

       if (id === "fullName" && !trimmedValue) {
         return "Full name is required.";
       }

       if (id === "email") {
         if (!trimmedValue) {
           return "Email address is required.";
         }

         if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmedValue)) {
           return "Enter a valid email address.";
         }
       }

       if (id === "phone" && trimmedValue) {
         const digits = trimmedValue.replace(/\D/g, "");

         if (digits.length !== 10) {
           return "Enter a 10-digit phone number, such as (555) 123-4567.";
         }
       }

       return "";
     }

     function validateForm() {
       state.errors = fields.reduce((errors, field) => {
         const message = validateField(field.id, state.values[field.id]);

         if (message) {
           errors[field.id] = message;
         }

         return errors;
       }, {});

       return Object.keys(state.errors).length === 0;
     }

     function FormField({ id, label, type, placeholder, required, autocomplete, helperText }) {
       const error = state.errors[id];
       const helperId = `${id}-helper`;
       const errorId = `${id}-error`;
       const describedBy = [
         helperText ? helperId : "",
         error ? errorId : "",
       ].filter(Boolean).join(" ");

       return `
         <div class="form-field">
           <label for="${id}">
             <span>${label}${required ? " *" : ""}</span>
             ${required ? "" : '<span class="optional">Optional</span>'}
           </label>
           <input
             id="${id}"
             name="${id}"
             type="${type}"
             value="${escapeHtml(state.values[id])}"
             placeholder="${placeholder}"
             autocomplete="${autocomplete}"
             ${required ? "required" : ""}
             ${describedBy ? `aria-describedby="${describedBy}"` : ""}
             aria-invalid="${error ? "true" : "false"}"
           >
           ${helperText ? `<p class="helper-text" id="${helperId}">${helperText}</p>` : ""}
           ${error ? `<p class="validation-message" id="${errorId}">${error}</p>` : ""}
         </div>
       `;
     }

     function ContactForm() {
       return `
         <section class="contact-card" aria-labelledby="contact-title">
           <h2 id="contact-title">Contact support</h2>
           <p>Tell us how to reach you and our team will follow up shortly.</p>

           <form id="support-form" novalidate>
             ${fields.map(FormField).join("")}
             <button class="submit-button" type="submit">Send request</button>
             <p class="form-status" role="status" aria-live="polite">
               ${state.submitted ? "Thanks! Your support request is ready to send." : ""}
             </p>
           </form>
         </section>
       `;
     }

     function SupportPage() {
       return `
         <div class="support-page">
           <section class="hero" aria-label="Support introduction">
             <div class="eyebrow">Support</div>
             <h1>How can we help?</h1>
             <p>
               Get fast, friendly help from our product support team. Share your details
               and we will connect you with the right specialist.
             </p>
           </section>
           ${ContactForm()}
         </div>
       `;
     }

     function attachHandlers() {
       const form = document.querySelector("#support-form");

       fields.forEach((field) => {
         const input = document.querySelector(`#${field.id}`);

         input.addEventListener("input", (event) => {
           state.values[field.id] = event.target.value;
           state.errors[field.id] = validateField(field.id, state.values[field.id]);
           state.submitted = false;
           render();
           document.querySelector(`#${field.id}`).focus();
         });

         input.addEventListener("blur", (event) => {
           state.values[field.id] = event.target.value;
           state.errors[field.id] = validateField(field.id, state.values[field.id]);
           render();
         });
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();
         state.submitted = validateForm();
         render();

         if (!state.submitted) {
           const firstInvalidField = fields.find((field) => state.errors[field.id]);
           document.querySelector(`#${firstInvalidField.id}`).focus();
         }
       });
     }

     function render() {
       document.querySelector("#app").innerHTML = SupportPage();
       attachHandlers();
     }

     render();
   </script>
 </body>
 </html>

